Config.DungeonData.data_drama_dungeon_info_length = 640
Config.DungeonData.data_drama_dungeon_info_cache = {}

function Config.DungeonData.data_drama_dungeon_info(slot0)
	if Config.DungeonData.data_drama_dungeon_info_cache[slot0] == nil then
		if not Config.DungeonData.data_drama_dungeon_info_table[slot0] then
			return
		end

		if not loadstring(string.format("return %s", slot1))() then
			return
		end

		Config.DungeonData.data_drama_dungeon_info_cache[slot0] = {
			name = slot1[1],
			mode = slot1[2],
			chapter_id = slot1[3],
			land_id = slot1[4],
			id = slot1[5],
			next_id = slot1[6],
			show_items = slot1[7],
			is_big = slot1[8],
			hook_items = slot1[9],
			hook_show_items = slot1[10],
			hook_lev_add = slot1[11],
			pos = slot1[12],
			unit_id = slot1[13],
			power = slot1[14],
			per_hook_items = slot1[15],
			talk_ids = slot1[16],
			energy_max = slot1[17],
			quick_show_items = slot1[18],
			lev_limit = slot1[19],
			floor = slot1[20]
		}
	end

	return Config.DungeonData.data_drama_dungeon_info_cache[slot0]
end

