function Config.DungeonData.data_drama_reward_fun(slot0)
	slot1 = Config.DungeonData.data_drama_reward[slot0]

	if DATA_DEBUG and slot1 == nil then
		print("(Config.DungeonData.data_drama_reward[" .. slot0 .. "])not found")

		return
	end

	return slot1
end

